// Replay cursor: advances one month per execution, 1997-02 .. 1998-12
const s = $getWorkflowStaticData('global');
const months = [];
for (let y = 1997; y <= 1998; y++) {
  for (let m = 1; m <= 12; m++) {
    const k = y + '-' + String(m).padStart(2, '0');
    if (k >= '1997-02') months.push(k);
  }
}
const i = s.idx ?? 0;
if (i >= months.length) return []; // replay finished, stop
s.idx = i + 1;
return [{ json: { month: months[i], step: i + 1, total: months.length } }];

// Parse JSON line printed by score_month.py on stdout
const raw = $input.first().json.stdout.trim().split('\n').pop();
const r = JSON.parse(raw);
return [{ json: r }];

// Parse report JSON and reconcile with the scoring step
const raw = $input.first().json.stdout.trim().split('\n').pop();
const r = JSON.parse(raw);
const scored = $('Parse Result').first().json;
if (!r.found) throw new Error('mart.alerts has no rows for ' + r.replay_month);
if (r.n_new + r.n_continuing !== r.n_alerts) throw new Error('new + continuing != n_alerts');
if (r.n_alerts !== scored.n_alerts) throw new Error('alert_report n_alerts differs from score_month n_alerts');
return [{ json: r }];

// Final memo. source: gemini (LLM text passed number check) | template (no new alerts, no LLM call
// by design) | fallback (LLM text missing or failed the check). Lists and glossary are added by code.
const rep = $('Parse report').first().json;
const inp = $input.first().json;
const llmText = (inp.content?.parts ?? []).map(p => p.text).filter(Boolean).join('\n').trim();

const template =
  `Bản tin ${rep.replay_month} (dữ liệu mô phỏng, replay Berka): chấm ${rep.n_scored} khoản, ` +
  `${rep.n_alerts} cảnh báo (${rep.n_new} mới, ${rep.n_continuing} đang tiếp diễn).` +
  (rep.n_new === 0 ? '\nTháng này không có cảnh báo mới.' : '') +
  rep.new_alerts.map(a => `\n- Khoản mới ${a.loan_id}: điểm ${a.score}; ${a.top_drivers}`).join('') +
  `\nĐây là dữ liệu mô phỏng, không phải hệ thống chạy thật.`;

let source, memoText, verified = null;
const problems = [];

if (rep.n_new === 0) {
  source = 'template';            // nothing new to narrate, so the LLM is not called
  memoText = template;
} else {
  const allowed = new Set();
  const add = v => { if (v !== null && v !== undefined && !Number.isNaN(Number(v))) allowed.add(Number(v)); };
  ['n_scored', 'n_alerts', 'n_new', 'n_continuing'].forEach(k => add(rep[k]));
  rep.new_alerts.forEach(a => {
    add(a.loan_id); add(a.score);
    for (const m of (a.top_drivers || '').matchAll(/\d+(?:\.\d+)?/g)) add(m[0]);
  });
  const body = llmText.split(rep.replay_month).join(' ');
  const found = [...body.matchAll(/\d+(?:\.\d+)?/g)].map(m => m[0]);
  if (inp.error) problems.push('llm error: ' + JSON.stringify(inp.error).slice(0, 150));
  if (!llmText) problems.push('empty memo');
  if (llmText && !llmText.includes(rep.replay_month)) problems.push('month label missing');
  found.forEach(t => { if (!allowed.has(Number(t))) problems.push('number not in report: ' + t); });
  rep.new_alerts.forEach(a => {
    if (!found.some(t => Number(t) === a.loan_id)) problems.push('loan_id missing: ' + a.loan_id);
  });
  verified = problems.length === 0;
  source = verified ? 'gemini' : 'fallback';
  memoText = verified ? llmText : template;
}

// Continuing alerts, listed by code (not by the LLM)
const cont = rep.continuing_alerts ?? [];
let contBlock = '';
if (cont.length) {
  contBlock = '\n\nCác khoản đang tiếp diễn (điểm cao nhất):' +
    cont.map(a => `\n- Khoản ${a.loan_id}: điểm ${a.score}; báo từ tháng ${a.first_alert_month}; ${a.top_drivers}`).join('');
  const hidden = rep.n_continuing - cont.length;
  if (hidden > 0) contBlock += `\n(Còn ${hidden} khoản đang tiếp diễn khác, không liệt kê.)`;
}

// Fixed glossary from the SQL definitions (no digits)
const glossary = {
  ever_neg: 'tài khoản từng có số dư âm tính đến thời điểm chấm điểm',
  hist_bal_avg: 'số dư trung bình trên các giao dịch lịch sử (trung bình theo giao dịch, không theo thời gian)',
  hist_neg_share: 'tỷ lệ giao dịch lịch sử có số dư âm (tính theo số giao dịch, không theo thời gian)',
  hist_penalty_cnt: 'số giao dịch lãi phạt do số dư âm (mã SANKC. UROK) trong lịch sử',
  lm_credit_ratio: 'tiền vào của tháng dương lịch gần nhất so với mức tiền vào trung bình hằng tháng trong lịch sử',
  lm_debit_ratio: 'tiền ra của tháng dương lịch gần nhất so với mức tiền ra trung bình hằng tháng trong lịch sử',
  loan_burden: 'khoản trả góp hằng tháng so với mức tiền vào trung bình hằng tháng trong lịch sử',
  loan_amount: 'số tiền vay',
  loan_duration: 'kỳ hạn vay (tính bằng tháng)',
  loan_age_k: 'số tháng kể từ giải ngân (đặc trưng kỹ thuật theo thời gian, không phải nguyên nhân rủi ro)',
};
const used = new Set();
[...rep.new_alerts, ...cont].forEach(a => {
  for (const m of (a.top_drivers || '').matchAll(/([a-z_]+)\(/g)) used.add(m[1]);
});
const lines = [...used].filter(n => glossary[n]).map(n => `- ${n}: ${glossary[n]}`);
const footer = lines.length
  ? '\n\nChú giải:\n' + lines.join('\n') +
    '\nSố trong ngoặc là mức đóng góp đã chuẩn hóa vào điểm; đóng góp dương làm tăng điểm. ' +
    'Đây là tương quan trong mô hình, không phải nguyên nhân.'
  : '';

return [{ json: {
  replay_month: rep.replay_month,
  memo: memoText + contBlock + footer,
  source, verified, problems,
} }];
